(function(){
  const style=document.createElement('style');
  style.id='learning-analysis-adjustments-style';
  style.textContent=`
  .learning-analysis-page .la-cross-table{table-layout:fixed;min-width:720px}.learning-analysis-page .la-cross-table th,.learning-analysis-page .la-cross-table td{vertical-align:middle;line-height:1.45}.learning-analysis-page .la-cross-table th:nth-child(1),.learning-analysis-page .la-cross-table td:nth-child(1){width:17%;text-align:left}.learning-analysis-page .la-cross-table th:nth-child(2),.learning-analysis-page .la-cross-table td:nth-child(2),.learning-analysis-page .la-cross-table th:nth-child(3),.learning-analysis-page .la-cross-table td:nth-child(3),.learning-analysis-page .la-cross-table th:nth-child(4),.learning-analysis-page .la-cross-table td:nth-child(4){width:14%;text-align:center}.learning-analysis-page .la-cross-table th:nth-child(5),.learning-analysis-page .la-cross-table td:nth-child(5){width:41%;text-align:left;white-space:normal}.learning-analysis-page .la-capability-student-table{table-layout:fixed;min-width:720px}.learning-analysis-page .la-capability-student-table th,.learning-analysis-page .la-capability-student-table td{vertical-align:middle;text-align:center}.learning-analysis-page .la-capability-student-table th:first-child,.learning-analysis-page .la-capability-student-table td:first-child{text-align:left;width:20%}.learning-analysis-page .la-capability-student-table th:last-child,.learning-analysis-page .la-capability-student-table td:last-child{text-align:left;width:18%;white-space:normal}.learning-analysis-page .la-capability-student-table .cap-good{color:#0b8c7e;font-weight:700}.learning-analysis-page .la-capability-student-table .cap-mid{color:#b4772d;font-weight:700}.learning-analysis-page .la-capability-student-table .cap-low{color:#bc6a54;font-weight:700}.learning-analysis-page .la-capability-table-wrap,.learning-analysis-page .la-cross-table-wrap{overflow-x:auto}
  `;
  document.head.appendChild(style);

  const adjust=()=>{
    const root=document.querySelector('[data-page="learning-analysis"]');if(!root||root.dataset.adjusted==='1')return;root.dataset.adjusted='1';
    const distribution=root.querySelector('[data-la-pane="distribution"]');
    if(distribution)distribution.innerHTML='<div class="la-detail-head"><div><h2>最新成绩 · 全员明细</h2><p>当前成绩任务：第 3 次作业 · 46 名有效学生 · 可继续下钻到学生分析</p></div><button class="btn secondary" onclick="laSetView(\'overview\')">← 返回班级概况</button></div><div class="la-capability-table-wrap"><table class="la-mini-table"><thead><tr><th>学生标识</th><th>班级</th><th>最新成绩</th><th>班级排名</th><th>较前次</th><th>状态</th></tr></thead><tbody><tr><td><b>学生 A***21</b></td><td>1 班</td><td class="score">94</td><td>3 / 46</td><td class="trend-up">+6.2</td><td><span class="tag ok">稳定高表现</span></td></tr><tr><td><b>学生 B***08</b></td><td>1 班</td><td class="score">78</td><td>21 / 46</td><td>+1.0</td><td><span class="tag">内容关注</span></td></tr><tr><td><b>学生 C***34</b></td><td>2 班</td><td class="score">62</td><td>38 / 46</td><td class="trend-down">-4.0</td><td><span class="tag">趋势下降</span></td></tr><tr><td><b>学生 D***17</b></td><td>2 班</td><td class="score">58</td><td>43 / 46</td><td class="trend-down">-6.0</td><td><span class="tag">需要关注</span></td></tr><tr><td><b>其余 42 名学生</b></td><td>1 / 2 班</td><td class="score">—</td><td>—</td><td>—</td><td><span class="tag gray">展开查看</span></td></tr></tbody></table></div><p class="la-footnote">这里展示的是当前最新成绩任务的全员结果，不是分数段教学解读；缺考、未提交和未匹配记录会在数据状态中单独标记。</p>';
    const cross=root.querySelector('[data-la-pane="content"] .la-cross-table');if(cross&&!cross.parentElement.classList.contains('la-cross-table-wrap')){const wrap=document.createElement('div');wrap.className='la-cross-table-wrap';cross.parentNode.insertBefore(wrap,cross);wrap.appendChild(cross)}
    const actions=root.querySelector('[data-la-pane="actions"]');
    if(actions){const headNote=actions.querySelector('.la-card-head p');if(headNote)headNote.textContent='建议综合成绩趋势、内容掌握度、课程能力指标和异常数据生成，直接用于教学安排。';actions.querySelector('.la-card-head .tag')?.remove();actions.querySelectorAll('.actions').forEach(node=>node.remove())}
    root.querySelectorAll('.la-card-head .tag').forEach(tag=>{if(tag.textContent.includes('AI')||tag.textContent.includes('待确认'))tag.textContent='基于分析'});
    const insight=root.querySelector('.la-insight');if(insight)insight.innerHTML='<strong>分析提示</strong><br>当前建议只基于 3 个有效成绩任务，可结合课堂表现补充判断。';
    const capabilityStudentCard=`<section class="la-card la-capability-student-card"><div class="la-card-head"><div><h2>全班课程能力指标掌握</h2><p>按学生逐人展示课程能力指标得分，支持识别班级内部差异</p></div><span class="tag ok">4 项指标 · 46 人</span></div><div class="la-capability-table-wrap"><table class="la-mini-table la-capability-student-table"><thead><tr><th>学生标识</th><th>抽象建模</th><th>逻辑推理</th><th>算法实践</th><th>沟通协作</th><th>达标指标</th></tr></thead><tbody><tr><td><b>学生 A***21</b></td><td class="cap-good">91%</td><td class="cap-good">86%</td><td class="cap-good">78%</td><td class="cap-good">74%</td><td>4 / 4</td></tr><tr><td><b>学生 B***08</b></td><td class="cap-good">78%</td><td class="cap-mid">66%</td><td class="cap-mid">58%</td><td class="cap-mid">61%</td><td>2 / 4</td></tr><tr><td><b>学生 C***34</b></td><td class="cap-mid">64%</td><td class="cap-mid">59%</td><td class="cap-low">47%</td><td class="cap-low">42%</td><td>1 / 4</td></tr><tr><td><b>学生 D***17</b></td><td class="cap-mid">61%</td><td class="cap-mid">63%</td><td class="cap-low">49%</td><td class="cap-low">51%</td><td>2 / 4</td></tr></tbody></table></div><p class="la-footnote">指标达标按单项 ≥ 60% 统计；其余学生可通过学生分析筛选继续展开。</p></section>`;
    const overview=root.querySelector('[data-la-pane="overview"]');
    const overviewCapability=overview?.querySelector('.la-capability-card');
    if(overviewCapability&&!overview.querySelector('.la-capability-student-card'))overviewCapability.insertAdjacentHTML('afterend',capabilityStudentCard);
    const students=root.querySelector('[data-la-pane="students"]');
    if(students&&!students.querySelector('.la-capability-student-card'))students.querySelector('.la-segment')?.insertAdjacentHTML('afterend',capabilityStudentCard)
  };
  const previousCoursePage=window.coursePage;window.coursePage=function(k){const out=previousCoursePage(k);if(k==='students')setTimeout(adjust,0);return out};coursePage=window.coursePage;
  window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#course/students'))setTimeout(adjust,0)});
  if(location.hash.startsWith('#course/students')){render();setTimeout(adjust,0)}
})();
